class Recordatorio { final String id,titulo; final String? descripcion; final DateTime fechaHora; final bool completado; Recordatorio({required this.id,required this.titulo,this.descripcion,required this.fechaHora,required this.completado}); factory Recordatorio.fromJson(Map<String,dynamic> j)=>Recordatorio(id:j['id'],titulo:j['titulo'],descripcion:j['descripcion'],fechaHora:DateTime.parse(j['fechaHora']),completado:j['completado']??false); Map<String,dynamic> toJson()=>{'titulo':titulo,'descripcion':descripcion,'fechaHora':fechaHora.toIso8601String(),'completado':completado}; bool get vencido=>!completado&&fechaHora.isBefore(DateTime.now()); }